const safe=(v,fall)=>Math.min(1,Math.max(0,Number.isFinite(Number(v))?Number(v):fall));
export class BattleSound{
 constructor(){let saved;try{saved=JSON.parse(localStorage.getItem('solar-relic-audio-v3')||'{}');}catch{saved={};}this.enabled=saved.enabled!==false;this.master=safe(saved.master,.86);this.effects=safe(saved.effects,.92);this.music=safe(saved.music,.32);this.ctx=null;this.active=0;this.lastBeat=0;this.step=0;this.buffers={};this.loading=false;}
 unlock(){if(!this.enabled)return;const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio)return;if(!this.ctx){this.ctx=new Audio;const c=this.ctx;this.out=c.createGain();this.out.gain.value=this.master*.6;const limiter=c.createDynamicsCompressor();limiter.threshold.value=-6;limiter.ratio.value=12;this.out.connect(limiter).connect(c.destination);this.noise=c.createBuffer(1,c.sampleRate*2,c.sampleRate);const data=this.noise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.loadSamples();}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}
 async loadSamples(){if(this.loading||typeof fetch==='undefined')return;this.loading=true;await Promise.all(['match','combo','totem','win','bomb','chime','nova','laser'].map(async name=>{try{const r=await fetch(`assets/sounds/${name}.wav`);if(r.ok)this.buffers[name]=await this.ctx.decodeAudioData(await r.arrayBuffer());}catch{}}));}
 sample(name,volume=.3,rate=1){if(!this.enabled||this.ctx?.state!=='running'||!this.buffers[name])return;const source=this.ctx.createBufferSource(),gain=this.ctx.createGain();source.buffer=this.buffers[name];source.playbackRate.value=rate;gain.gain.value=volume*this.effects;source.connect(gain).connect(this.out);source.start();}
 setEnabled(on){this.enabled=!!on;if(this.ctx)this.out.gain.setTargetAtTime(this.enabled?this.master*.6:0,this.ctx.currentTime,.04);}
 tone(freq,duration=.2,gain=.12,type='sine',when=0,endFreq=freq,pan=0,music=false){const c=this.ctx;if(!this.enabled||!c||c.state!=='running'||this.active>38)return;const t=Math.max(c.currentTime,when||c.currentTime),o=c.createOscillator(),v=c.createGain();o.type=type;o.frequency.setValueAtTime(Math.max(25,freq),t);o.frequency.exponentialRampToValueAtTime(Math.max(25,endFreq),t+duration);const amount=gain*(music?this.music:this.effects);v.gain.setValueAtTime(.0001,t);v.gain.exponentialRampToValueAtTime(Math.max(.0002,amount),t+.012);v.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(v);if(c.createStereoPanner){const p=c.createStereoPanner();p.pan.value=pan;v.connect(p).connect(this.out);}else v.connect(this.out);this.active++;o.onended=()=>this.active--;o.start(t);o.stop(t+duration+.02);}
 rush(duration,frequency,amount,when=0){const c=this.ctx;if(!this.enabled||!c||c.state!=='running'||this.active>38)return;const t=Math.max(c.currentTime,when||c.currentTime),source=c.createBufferSource(),filter=c.createBiquadFilter(),v=c.createGain();source.buffer=this.noise;filter.type='lowpass';filter.frequency.value=frequency;v.gain.setValueAtTime(.0001,t);v.gain.exponentialRampToValueAtTime(amount*this.effects,t+.01);v.gain.exponentialRampToValueAtTime(.0001,t+duration);source.connect(filter).connect(v).connect(this.out);this.active++;source.onended=()=>this.active--;source.start(t);source.stop(t+duration+.02);}
 match(){this.sample('match',.38);this.tone(510,.13,.13,'triangle');this.tone(910,.2,.07,'sine',this.ctx?.currentTime+.035);}
 charge(){this.tone(380,.14,.14,'sine',0,530);}
 spell(color,strong=1){this.sample('totem',.28,strong>1?.92:1);const t=this.ctx?.currentTime||0,s=Math.min(1.5,strong);
  if(color===0){[440,660,880].forEach((f,i)=>this.tone(f,.48,.12*s,'sine',t+i*.07,f*1.25));this.rush(.45,2500,.08*s,t);}
  if(color===1){this.tone(145,.7,.38*s,'sine',t,35);this.rush(.63,850,.29*s,t+.02);for(let i=0;i<3;i++)this.tone(310+i*60,.12,.11*s,'sawtooth',t+i*.06,70);}
  if(color===2){this.rush(.08,6800,.43*s,t);this.tone(105,.7,.38*s,'sine',t+.01,29);this.rush(1.2,410,.25*s,t+.18);this.rush(1.4,240,.18*s,t+.45);}
  if(color===3){[330,440,550,880].forEach((f,i)=>this.tone(f,1.1,.15*s,'sine',t+i*.05,f));this.tone(110,.7,.21*s,'triangle',t,55);}
  if(color===4){[520,410,310].forEach((f,i)=>this.tone(f,.65,.16*s,'sine',t+i*.08,f*.76));this.rush(.7,1400,.1*s,t);}
  if(color===5){for(let i=0;i<6;i++)this.tone(1180-i*120,.07,.12*s,'square',t+i*.095,650);this.tone(155,.85,.16*s,'triangle',t,290);}
  if(color===6){this.tone(310,.48,.22*s,'sine',t,650);this.rush(.55,3300,.18*s,t);[650,830,970].forEach((f,i)=>this.tone(f,.17,.08*s,'sine',t+i*.06,f*1.4));}
  if(color===7){this.tone(92,.65,.4*s,'triangle',t,36);this.rush(.48,550,.3*s,t+.03);for(let i=0;i<3;i++)this.tone(190+i*40,.14,.11*s,'sawtooth',t+i*.07,85);}
  if(color===8){this.rush(.9,2100,.26*s,t);this.tone(420,.76,.18*s,'sine',t,820);this.tone(625,.65,.11*s,'triangle',t+.08,990);}
 }
 combo(id){const t=this.ctx?.currentTime||0;if(id==='ice'){this.rush(.42,4800,.25,t);this.tone(1390,.6,.18,'sine',t,400);}else if(id==='storm'){this.spell(2,1.3);this.tone(70,.9,.22,'sine',t,28);}else if(id==='magma'){this.spell(1,1.2);this.tone(74,.85,.25,'triangle',t,33);}else if(id==='eclipse'){this.spell(4,1.25);this.tone(170,.8,.18,'sine',t,510);}else if(id==='inferno'){this.spell(1,1.5);this.rush(.9,1550,.38,t+.12);this.tone(64,1,.35,'sine',t+.1,26);}else if(id==='reef'){this.spell(6,1.2);this.tone(480,.8,.18,'sine',t,920);this.tone(720,.9,.13,'triangle',t+.09,480);}else if(id==='overload'){this.spell(2,1.5);this.rush(1.35,420,.38,t+.22);this.tone(58,1.35,.38,'sine',t+.1,26);}else this.spell(0,1.25);}
 counter(){this.tone(115,.42,.31,'sawtooth',0,42);this.rush(.3,950,.2);}
 guard(){const t=this.ctx?.currentTime||0;this.tone(660,.34,.17,'triangle',t,430);this.tone(990,.28,.11,'sine',t+.035,720);this.rush(.22,3300,.09,t);}
 stun(){const t=this.ctx?.currentTime||0;this.tone(370,.42,.15,'sine',t,190);this.tone(280,.53,.1,'triangle',t+.12,105);}
 victory(){const t=this.ctx?.currentTime||0;[392,494,587,784,988].forEach((f,i)=>this.tone(f,.65,.18,'triangle',t+i*.09));}
 defeat(){const t=this.ctx?.currentTime||0;[340,260,190,120].forEach((f,i)=>this.tone(f,.5,.13,'triangle',t+i*.12,f*.72));}
 beat(){const c=this.ctx;if(!this.enabled||!c||c.state!=='running'||document.hidden||this.music===0)return;const now=c.currentTime;if(now-this.lastBeat<.52)return;this.lastBeat=now;const step=this.step++,roots=[110,98,130.8,87.3];const root=roots[Math.floor(step/8)%4];if(step%4===0)this.tone(root,.58,.09,'sine',now,root*.95,0,true);if(step%2===0)this.tone(root*2*(step%8===4?1.5:1.25),.27,.045,'triangle',now,root*2,0,true);}
}
